    /**
     * Method to retrieve the Aircraft via an AircraftPrimaryKey.
     * @param 	id Long
     * @return 	Aircraft
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Aircraft handle( FindAircraftQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAircraftId() );
    }
    
    /**
     * Method to retrieve a collection of all Aircrafts
     *
     * @param	query	FindAllAircraftQuery 
     * @return 	List<Aircraft> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Aircraft> handle( FindAllAircraftQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAircraft,
 * but only if the id matches
 *
 * @param		entity	Aircraft
 */
	protected void emitFindAircraft( Aircraft entity ) {
		LOGGER.info("handling emitFindAircraft" );
		
	    queryUpdateEmitter.emit(FindAircraftQuery.class,
	                            query -> query.getFilter().getAircraftId().equals(entity.getAircraftId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAircraft
	 * 
	 * @param		entity	Aircraft
	 */
	protected void emitFindAllAircraft( Aircraft entity ) {
		LOGGER.info("handling emitFindAllAircraft" );
		
	    queryUpdateEmitter.emit(FindAllAircraftQuery.class,
	                            query -> true,
	                            entity);
	}

